// Known radiosonde launch sites (4.0): a built-in list of the stations still launching, plus the user's own file, to name the sites
// OnAir learns from the sondes it hears (sonde_sites.h: before 4.0 every learned site was "Site 1", "Site 2" ... until renamed by hand)
// and to show every launch site in view on the radiosonde map.
// Built-in list: the station list of the Integrated Global Radiosonde Archive version 2 (IGRA 2) of NOAA's National Centers for
// Environmental Information, a US Government work in the public domain; the stations with soundings in 2025 or later. Generated by
// tools/gen_sonde_sites.py (it says how). Source: https://www.ncei.noaa.gov/data/integrated-global-radiosonde-archive/doc/igra2-station-list.txt
// (Durre et al. 2016, doi:10.7289/V5X63K0Q). Names are the archive's (at most 30 characters, put in title case).
// The user's file (<data folder>/sonde-sites-known.txt): one site per line, "name; latitude; longitude[; altitude m]" (commas or tabs
// also separate the fields), # starts a comment. A user site wins over a built-in one within 2 km.
#pragma once
#include <cstddef>
#include <string>
#include <vector>

namespace dect2 {

struct KnownSondeSite { const char* id; int wmo; double lat, lon, altM; const char* name; };
const KnownSondeSite* builtinSondeSites(size_t& n);   // sonde_sites_known.cpp (generated)

struct SondeSiteRef {
    std::string name;
    double lat = 0, lon = 0, altM = 0;
    int wmo = 0;               // WMO station number, 0 when none
    bool user = false;         // from the user's file
};

double sondeSiteKm(double la1, double lo1, double la2, double lo2);   // great-circle distance

class KnownSondeSites {
public:
    KnownSondeSites();                                     // the built-in list
    int addUserText(const std::string& text);              // the user's file; returns the sites read
    const std::vector<SondeSiteRef>& all() const { return all_; }
    // the nearest site within maxKm (a user site within maxKm before any built-in one); nullptr when none
    const SondeSiteRef* nearest(double lat, double lon, double maxKm, double* km = nullptr) const;
    // the sites inside a box (west > east: the box crosses the 180 degree line), user sites first, at most maxN spread over the list
    std::vector<const SondeSiteRef*> inBox(double south, double west, double north, double east, size_t maxN = 400) const;
    static constexpr double kNameKm = 15;   // a learned site this close to a known one takes its name (first fixes are often a few km out)
private:
    std::vector<SondeSiteRef> all_;
    size_t builtin_ = 0;
};

}  // namespace dect2
